const fs = require('fs');
const path = require('path');
require('dotenv').config({ path: '.env.test' });

const MIGRATIONS_DIR = './migrations';

/**
 * Get the database connection string from environment variables
 * @returns {Object} Object with connectionString and maskedConnectionString properties
 */
function getDatabaseConnectionString() {
  const connectionString = process.env.DATABASE_URL;

  if (!connectionString) {
    throw new Error('DATABASE_URL is not set in the environment variables.');
  }

  // Mask the password in the connection string for security
  const maskedConnectionString = connectionString.replace(/:([^:@]+)@/, ':****@');

  return {
    connectionString,
    maskedConnectionString
  };
}

/**
 * Simulate a database connection (for demonstration purposes)
 * @param {string} connectionString - The database connection string
 */
function connectToDatabase(connectionString) {
  // In a real implementation, you would actually connect to the database here
  // For now, we just log that we "connected" successfully
  const { maskedConnectionString } = getDatabaseConnectionString();
  console.log('✅ Successfully connected to database:');
  console.log(`   Connection String: ${maskedConnectionString}`);
}

/**
 * Get all SQL migration files from the migrations directory
 * @returns {string[]} Array of migration file paths sorted by filename
 */
function getMigrationFiles() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
    return [];
  }

  // Read all files in the migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter for SQL files and sort them alphabetically
  const sqlFiles = files
    .filter(file => file.endsWith('.sql'))
    .sort();

  return sqlFiles;
}

/**
 * Main migration function - logs each migration file that would be applied
 */
function migrate() {
  console.log('🔄 Starting migration process...\n');

  try {
    // Resolve and log database connection
    const { maskedConnectionString } = getDatabaseConnectionString();
    connectToDatabase(maskedConnectionString);
    console.log('');

    // Check for migration files
    console.log('📂 Checking for migration files...\n');

    const migrationFiles = getMigrationFiles();

    if (migrationFiles.length === 0) {
      console.log('✅ No migration files found to apply.');
      return;
    }

    console.log(`📋 Found ${migrationFiles.length} migration file(s):`);
    console.log('');

    // Log each migration file in order
    migrationFiles.forEach((file, index) => {
      const filePath = path.join(MIGRATIONS_DIR, file);
      const fileStats = fs.statSync(filePath);
      const fileSize = (fileStats.size / 1024).toFixed(2);

      console.log(`  [${index + 1}] ${file}`);
      console.log(`      Path: ${filePath}`);
      console.log(`      Size: ${fileSize} KB`);
      console.log('');
    });

    console.log('🔍 The above migrations would be applied in the order shown.');
  } catch (error) {
    console.error('❌ Migration failed:');
    console.error(`   ${error.message}`);
    process.exit(1);
  }
}

// Run the migration function
if (require.main === module) {
  migrate();
}

module.exports = { migrate, getMigrationFiles, getDatabaseConnectionString };

