/**
 * Send audit log to the migration audit service
 * @param {Object} envData - Environment variables to audit
 * @returns {Promise<Object>} Response from the audit service
 */
async function sendAuditLog(envData) {
  const auditData = {
    timestamp: new Date().toISOString(),
    event: 'migration_pre_check',
    environment: envData
  };

  console.log('📨 Sending audit log to compliance service...');
  console.log(`   Service: ${AUDIT_SERVICE_URL}`);

  try {
    const response = await fetch(AUDIT_SERVICE_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(auditData),
    });

    if (!response.ok) {
      throw new Error(`Audit service responded with status ${response.status}`);
    }

    const result = await response.json();
    console.log('✅ Audit log sent successfully:');
    console.log(`   Audit ID: ${result.audit_id || 'N/A'}`);
    console.log('');
    return result;
  } catch (error) {
    if (error.message.includes('ECONNREFUSED') || error.message.includes('fetch is not defined')) {
      console.log('⚠️  Audit service unavailable, continuing anyway...');
      console.log('');
      return null;
    }
    console.error('❌ Failed to send audit log:');
    console.error(`   ${error.message}`);
    console.error('   Continuing anyway...\n');
    return null;
  }
}

