  if (migrationFiles.length === 0) {
    console.log('No migration files found to apply.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s) to apply:\n`);

  migrationFiles.forEach((file, index) => {
    const fullPath = path.join(MIGRATIONS_DIR, file);
    const stats = fs.statSync(fullPath);
    const fileSize = (stats.size / 1024).toFixed(2);

    console.log(`${index + 1}. ${file} (${fileSize} KB)`);
  });

  console.log(`\nTotal: ${migrationFiles.length} migration(s) would be applied.`);
}

// Run the migration script
if (require.main === module) {
  migrate();
}

module.exports = { getMigrationFiles, migrate, MIGRATIONS_DIR };

