#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = './migrations';

/**
 * Get all SQL migration files from the migrations directory, sorted alphabetically
 * @returns {string[]} Array of migration filenames
 */
function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
      process.exit(1);
    }

    // Read all files in the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files and sort them alphabetically
    // This assumes files are named with prefixes like 001_create_users.sql, 002_add_votes.sql, etc.
    const migrationFiles = files
      .filter(file => file.endsWith('.sql') || file.endsWith('.SQL'))
      .sort();

    return migrationFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Main function to run the migration script
 */
function migrate() {
  console.log('🔄 Migration - Analyzing migrations...\n');
  console.log(`📂 Migrations directory: ${path.resolve(MIGRATIONS_DIR)}`);

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('\n✅ No migration files found.');
    return;
  }

  console.log(`\n📋 Found ${migrationFiles.length} migration file(s):\n`);

  migrationFiles.forEach((file, index) => {
    const fullPath = path.join(MIGRATIONS_DIR, file);
    console.log(`  ${index + 1}. ${file}`);
    console.log(`     Path: ${fullPath}`);

    // Optionally read and display the first line as a description
