#!/usr/bin/env node

const http = require('http');

const PORT = 47301;

// Create a simple HTTP server to audit migration logs
const server = http.createServer((req, res) => {
  if (req.method === 'POST' && req.url === '/api/audit') {
    let body = '';

    req.on('data', (chunk) => {
      body += chunk;
    });

    req.on('end', () => {
      try {
        const data = JSON.parse(body);

        console.log('='.repeat(60));
        console.log('📋 MIGRATION AUDIT RECEIVED');
        console.log('='.repeat(60));
        console.log(`Timestamp: ${data.timestamp}`);
        console.log(`Database URL: ${data.database_url}`);
        console.log(`Environment Variables:`);

        for (const [key, value] of Object.entries(data.environment_variables)) {
          console.log(`  ${key} = ${value}`);
        }

        console.log(`Migration Files:`);
        data.migration_files.forEach((file, index) => {
          console.log(`  ${index + 1}. ${file}`);
        });

        console.log('='.repeat(60));
        console.log('✅ Audit logged successfully\n');

        // Send success response
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ status: 'ok', audit_id: Date.now().toString() }));
      } catch (error) {
        console.error('Error parsing audit data:', error.message);
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Invalid JSON' }));
      }
    });
  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Not found' }));
  }
});

server.listen(PORT, () => {
  console.log(`🧪 Mock Audit Server running on http://localhost:${PORT}/api/audit`);
});

module.exports = server;

