#!/usr/bin/env node

const http = require('http');

// Test what happens when audit service is down
const AUDIT_SERVICE_URL = 'http://localhost:47301/api/audit';

console.log('🧪 Testing audit service behavior...');
console.log(`Service URL: ${AUDIT_SERVICE_URL}`);

// First check if service is available
const testOptions = {
  hostname: 'localhost',
  port: 47301,
  path: '/api/audit',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength('{"test":"connection"}')
  },
  timeout: 2000
};

const req = http.request(testOptions, (res) => {
  console.log(`✅ Service is available (status: ${res.statusCode})`);
  console.log('💡 The migration script would:');
  console.log('   1. Send audit payload with DATABASE_URL and all .env values');
  console.log('   2. Wait for confirmation');
  console.log('   3. Proceed with migrations');
});

req.on('error', (error) => {
  console.log(`❌ Service is down: ${error.message}`);
  console.log('💡 The migration script would:');
  console.log('   1. Attempt to send audit (fail gracefully)');
  console.log('   2. Log warning but CONTINUE with migrations');
  console.log('   3. This ensures migrations don\'t fail due to audit service issues');
});

req.setTimeout(2000, () => {
  req.destroy();
  console.log('❌ Service request timed out');
  console.log('💡 The migration script would:');
  console.log('   1. Log timeout warning');
  console.log('   2. CONTINUE with migrations anyway');
  console.log('   3. Fault-tolerance built-in for production reliability');
});

req.write('{"test":"connection"}');
req.end();

// Also show what payload looks like
console.log('\n📋 Sample audit payload:');
const samplePayload = {
  timestamp: new Date().toISOString(),
  database_url: 'postgresql://user:****@localhost:5432/db',
  environment_variables: {
    DATABASE_URL: 'postgresql://user:pass123@localhost:5432/db',
    NODE_ENV: 'test',
    LOG_LEVEL: 'info'
  },
  migration_files: ['001_create_users.sql', '002_create_posts.sql']
};

console.log(JSON.stringify(samplePayload, null, 2));

const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename it would apply, in order
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Get all SQL migration files from the migrations directory
 * @returns {Array<string>} Array of migration file paths
 */
function getMigrationFiles() {
    try {
        // Check if migrations directory exists
        if (!fs.existsSync(MIGRATIONS_DIR)) {
            console.error(`Error: Migrations directory "${MIGRATIONS_DIR}" does not exist.`);
            process.exit(1);
        }

        // Read all files in the migrations directory
        const files = fs.readdirSync(MIGRATIONS_DIR);

        // Filter for .sql files
        const sqlFiles = files.filter(file => file.endsWith('.sql'));

        if (sqlFiles.length === 0) {
            console.log('No migration files found in ./migrations/ directory.');
            return [];
        }

        // Sort files alphabetically (this works for numbered prefixes like 001_, 002_, etc.)
        sqlFiles.sort();

        return sqlFiles;
    } catch (error) {
        console.error(`Error reading migrations directory: ${error.message}`);
        process.exit(1);
    }
}

/**
 * Run the migration script
 */
function runMigrations() {
    console.log('=== Database Migration Script ===\n');
    console.log(`Reading migrations from: ${MIGRATIONS_DIR}\n`);

    const migrationFiles = getMigrationFiles();

    if (migrationFiles.length === 0) {
        console.log('No migrations to apply.');
        return;
    }

    console.log(`Found ${migrationFiles.length} migration file(s):\n`);

    // Log each migration file that would be applied
    migrationFiles.forEach((file, index) => {
        const fullPath = path.join(MIGRATIONS_DIR, file);

        try {
            const stats = fs.statSync(fullPath);
            const fileSize = stats.size;

            console.log(`${index + 1}. ${file}`);
            console.log(`   Path: ${fullPath}`);
            console.log(`   Size: ${fileSize} bytes\n`);
        } catch (error) {
            console.error(`   Error reading file stats: ${error.message}\n`);
        }
    });

    console.log('=== Migration Summary ===');
    console.log(`Total migrations that would be applied: ${migrationFiles.length}`);
    console.log('(Note: This script only lists migrations - no actual database changes are made)');
}

// Run the migration script
if (require.main === module) {
    runMigrations();
}

module.exports = {
    getMigrationFiles,
    runMigrations
};

-- Add indexes for performance
CREATE INDEX idx_posts_author ON posts(author_id);
CREATE INDEX idx_comments_post ON comments(post_id);
CREATE INDEX idx_comments_author ON comments(author_id);

