const server = http.createServer((req, res) => {
    let body = '';

    req.on('data', chunk => {
        body += chunk.toString();
    });

    req.on('end', () => {
        console.log('=== Audit Service Request ===');
        console.log(`Method: ${req.method}`);
        console.log(`URL: ${req.url}`);
        console.log(`Headers: ${JSON.stringify(req.headers, null, 2)}`);
        console.log(`Body: ${body}`);
        console.log('============================\n');

        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ success: true, message: 'Logged' }));
    });
});

server.listen(47301, () => {
    console.log('Test audit server listening on http://localhost:47301/api/audit\n');
});

