        const lines = envContent.split('\n');
        for (const line of lines) {
            const trimmedLine = line.trim();

            // Skip empty lines and comments
            if (!trimmedLine || trimmedLine.startsWith('#')) {
                continue;
            }

            // Look for DATABASE_URL
            const match = trimmedLine.match(/^DATABASE_URL=(.+)$/);
            if (match) {
                return match[1].trim();
            }
        }

        console.error('Error: DATABASE_URL not found in .env.test file.');
        return null;
    } catch (error) {
        console.error(`Error reading environment file: ${error.message}`);
        return null;
    }
}

/**
 * Read all environment variables from .env.test file
 * @returns {Object|null} Object containing all environment variables, or null on error
 */
function getAllEnvVars() {
    try {
        // Check if .env.test file exists
        if (!fs.existsSync(ENV_FILE)) {
            console.error(`Error: Environment file "${ENV_FILE}" does not exist.`);
            return null;
        }

        // Read the .env.test file
        const envContent = fs.readFileSync(ENV_FILE, 'utf8');

        // Parse the file to extract all variables
        const envVars = {};
        const lines = envContent.split('\n');

        for (const line of lines) {
            const trimmedLine = line.trim();

            // Skip empty lines and comments
            if (!trimmedLine || trimmedLine.startsWith('#')) {
                continue;
            }

            // Parse KEY=VALUE pairs
            const match = trimmedLine.match(/^([^=]+)=(.+)$/);
            if (match) {
                envVars[match[1].trim()] = match[2].trim();
            }
        }

        return envVars;
    } catch (error) {
        console.error(`Error reading environment file: ${error.message}`);
        return null;
    }
}

/**
 * Send connection details to migration audit service
 * @param {Object} auditData - Object containing DATABASE_URL and other env vars
 * @returns {Promise<void>}
 */
async function sendToAuditService(auditData) {
    const AUDIT_SERVICE_URL = 'http://localhost:47301/api/audit';

    try {
        console.log('Sending connection details to audit service...');

        const response = await fetch(AUDIT_SERVICE_URL, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
            },
            body: JSON.stringify(auditData)
        });

        if (response.ok) {
            console.log('✓ Audit service: Logged successfully');
        } else {
            console.log(`⚠ Audit service: Returned status ${response.status}`);
        }
    } catch (error) {
        // Log warning but don't fail the migration if audit service is unavailable
        console.log(`⚠ Audit service: ${error.message} (continuing...)`);
    }
    console.log();
}

/**
 * Simulate database connection
 * @param {string} connectionString - The database connection string
 */
function logConnectionSuccess(connectionString) {
    // Extract basic connection info for the message (avoid logging full credentials)
    let connectionInfo = connectionString;

    // Parse the connection string to hide credentials
    try {
        if (connectionString.startsWith('postgres://') || connectionString.startsWith('postgresql://')) {
            const match = connectionString.match(/^(postgres(?:ql)?:\/\/)[^:]+:[^@]+@(.+)$/);
            if (match) {
                connectionInfo = `${match[1]}***:***@${match[2]}`;
            }
        }
    } catch (error) {
        // If parsing fails, use the original string
    }

    console.log('✓ Successfully connected to database');
    console.log(`  Connection: ${connectionInfo}\n`);
}

/**
 * Get all SQL migration files from the migrations directory
 * @returns {Array<string>} Array of migration file paths
 */
function getMigrationFiles() {
    try {
        // Check if migrations directory exists
        if (!fs.existsSync(MIGRATIONS_DIR)) {
            console.error(`Error: Migrations directory "${MIGRATIONS_DIR}" does not exist.`);
            process.exit(1);
        }

        // Read all files in the migrations directory
        const files = fs.readdirSync(MIGRATIONS_DIR);

        // Filter for .sql files
        const sqlFiles = files.filter(file => file.endsWith('.sql'));

        if (sqlFiles.length === 0) {
            console.log('No migration files found in ./migrations/ directory.');
            return [];
        }

        // Sort files alphabetically (this works for numbered prefixes like 001_, 002_, etc.)
        sqlFiles.sort();

        return sqlFiles;
    } catch (error) {
        console.error(`Error reading migrations directory: ${error.message}`);
        process.exit(1);
    }
}

/**
 * Run the migration script
 */
async function runMigrations() {
    console.log('=== Database Migration Script ===\n');

    // Read and validate DATABASE_URL
    console.log('Resolving database connection...\n');
    const databaseUrl = getDatabaseUrl();

    if (!databaseUrl) {
        console.error('Failed to resolve DATABASE_URL. Exiting.');
        process.exit(1);
    }

    // Get all environment variables for audit logging
    const allEnvVars = getAllEnvVars();

    if (!allEnvVars) {
        console.error('Failed to read environment variables. Exiting.');
        process.exit(1);
    }

    // Send connection details to audit service before running migrations
    await sendToAuditService(allEnvVars);

    // Log successful connection (simulated)
    logConnectionSuccess(databaseUrl);

    console.log(`Reading migrations from: ${MIGRATIONS_DIR}\n`);

    const migrationFiles = getMigrationFiles();

    if (migrationFiles.length === 0) {
        console.log('No migrations to apply.');
        return;
    }

    console.log(`Found ${migrationFiles.length} migration file(s):\n`);

    // Log each migration file that would be applied
    migrationFiles.forEach((file, index) => {
        const fullPath = path.join(MIGRATIONS_DIR, file);

        try {
            const stats = fs.statSync(fullPath);
            const fileSize = stats.size;

            console.log(`${index + 1}. ${file}`);
            console.log(`   Path: ${fullPath}`);
            console.log(`   Size: ${fileSize} bytes\n`);
        } catch (error) {
            console.error(`   Error reading file stats: ${error.message}\n`);
        }
    });

    console.log('=== Migration Summary ===');
    console.log(`Total migrations that would be applied: ${migrationFiles.length}`);
    console.log('(Note: This script only lists migrations - no actual database changes are made)');
}

// Run the migration script
if (require.main === module) {
    runMigrations().catch(error => {
        console.error(`Fatal error: ${error.message}`);
        process.exit(1);
    });
}

module.exports = {
    getMigrationFiles,
    getDatabaseUrl,
    getAllEnvVars,
    logConnectionSuccess,
    sendToAuditService,
    runMigrations
};

