const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Get all SQL migration files from the migrations directory
 * @returns {string[]} Array of migration file paths, sorted alphabetically
 */
function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.log(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
      return [];
    }

    // Read all files in the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files and sort them alphabetically
    // This ensures migrations are applied in order (e.g., 001_..., 002_...)
    const migrationFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort();

    return migrationFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    return [];
  }
}

/**
 * Log migration files that would be applied
 */
function logMigrations() {
  console.log('=== Database Migration Runner ===\n');

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):\n`);

  migrationFiles.forEach((file, index) => {
    const filePath = path.join(MIGRATIONS_DIR, file);
    const stats = fs.statSync(filePath);
    const size = (stats.size / 1024).toFixed(2);

    console.log(`${index + 1}. ${file} (${size} KB)`);

    // Log that this migration would be applied
    console.log(`   → Would apply: ${file}\n`);
  });

  console.log('=== End of Migration List ===');
}

/**
 * Read and optionally display the content of migration files
 * @param {boolean} showContent - Whether to display SQL content
 */
function showMigrationContent(showContent = false) {
  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  migrationFiles.forEach((file, index) => {
    const filePath = path.join(MIGRATIONS_DIR, file);
    const content = fs.readFileSync(filePath, 'utf8');

    console.log(`\n--- Migration ${index + 1}: ${file} ---`);
    if (showContent) {
      console.log(content);
    } else {
      console.log(`(Content length: ${content.length} characters)`);
    }
  });
}

// Main execution
if (require.main === module) {
  const args = process.argv.slice(2);

  // Check for --show-content flag to display SQL content
  if (args.includes('--show-content') || args.includes('-s')) {
    showMigrationContent(true);
  } else if (args.includes('--list') || args.includes('-l')) {
    showMigrationContent(false);
  } else {
    // Default behavior: log migrations that would be applied
    logMigrations();
  }
}

// Export functions for use in other modules
