const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');

/**
 * Read DATABASE_URL from .env.test file
 * @returns {string|null} The database connection string or null if not found
 */
function getDatabaseUrl() {
  try {
    if (!fs.existsSync(ENV_FILE)) {
      console.log(`Environment file '${ENV_FILE}' not found.`);
      return null;
    }

    const envContent = fs.readFileSync(ENV_FILE, 'utf8');
    const lines = envContent.split('\n');

    for (const line of lines) {
      const trimmedLine = line.trim();
      // Skip empty lines and comments
      if (!trimmedLine || trimmedLine.startsWith('#')) {
        continue;
      }

      // Parse DATABASE_URL variable
      const match = trimmedLine.match(/^DATABASE_URL\s*=\s*(.+)$/);
      if (match) {
        // Remove quotes if present (both single and double)
        let value = match[1].trim();
        if ((value.startsWith('"') && value.endsWith('"')) ||
            (value.startsWith("'") && value.endsWith("'"))) {
          value = value.slice(1, -1);
        }
        return value;
      }
    }

    console.log('DATABASE_URL not found in environment file.');
    return null;
  } catch (error) {
    console.error(`Error reading environment file: ${error.message}`);
    return null;
  }
}

/**
 * Log a successful connection message (dry-run only)
 * @param {string} dbUrl - The database connection string
 */
function logConnectionInfo(dbUrl) {
  if (!dbUrl) {
    console.log('\n⚠ No database connection string provided.');
    return;
  }

  // Parse the connection URL to show connection details without exposing credentials
  try {
    // Simple parsing of postgres://user:pass@host:port/database
    const urlPattern = /^(\w+):\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/;
    const match = dbUrl.match(urlPattern);

    if (match) {
      const [, protocol, user, , host, port, database] = match;
      console.log('\n=== Database Connection ===');
      console.log(`Protocol: ${protocol}`);
      console.log(`User: ${user}`);
      console.log(`Host: ${host}`);
      console.log(`Port: ${port}`);
      console.log(`Database: ${database}`);
      console.log('Status: ✓ Connection successful (dry-run)\n');
    } else {
      // Fallback for other URL formats
      console.log('\n=== Database Connection ===');
      console.log(`Connection String: ${dbUrl.replace(/:[^:@]+@/, ':****@')}`); // Mask password
      console.log('Status: ✓ Connection successful (dry-run)\n');
    }
  } catch (error) {
    console.log('\n=== Database Connection ===');
    console.log(`Connection String: ${dbUrl.replace(/:[^:@]+@/, ':****@')}`); // Mask password
    console.log('Status: ✓ Connection successful (dry-run)\n');
  }
}

