const fs = require('fs');
const path = require('path');
const http = require('http');

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');
const AUDIT_SERVICE_URL = 'http://localhost:47301/api/audit';

/**
 * Read all environment variables from .env.test file
 * @returns {Object} Object containing all environment variables
 */
function getEnvVariables() {
  try {
    if (!fs.existsSync(ENV_FILE)) {
      console.log(`Environment file '${ENV_FILE}' not found.`);
      return {};
    }

    const envContent = fs.readFileSync(ENV_FILE, 'utf8');
    const lines = envContent.split('\n');
    const envVars = {};

    for (const line of lines) {
      const trimmedLine = line.trim();
      // Skip empty lines and comments
      if (!trimmedLine || trimmedLine.startsWith('#')) {
        continue;
      }

      // Parse KEY=VALUE format
      const match = trimmedLine.match(/^([^=]+)=(.+)$/);
      if (match) {
        const key = match[1].trim();
        let value = match[2].trim();
        // Remove quotes if present (both single and double)
        if ((value.startsWith('"') && value.endsWith('"')) ||
            (value.startsWith("'") && value.endsWith("'"))) {
          value = value.slice(1, -1);
        }
        envVars[key] = value;
      }
    }

    return envVars;
  } catch (error) {
    console.error(`Error reading environment file: ${error.message}`);
    return {};
  }
}

/**
 * Read DATABASE_URL from .env.test file
 * @returns {string|null} The database connection string or null if not found
 */
function getDatabaseUrl() {
  const envVars = getEnvVariables();
  return envVars.DATABASE_URL || null;
}

/**
 * POST environment variables to the migration audit service
 * @param {Object} envVars - Object containing environment variables to audit
 * @param {boolean} debug - Whether to log the payload being sent
 * @returns {Promise<boolean>} True if audit was successful, false otherwise
 */
async function sendAuditLog(envVars, debug = false) {
  return new Promise((resolve) => {
    const payload = {
      timestamp: new Date().toISOString(),
      eventType: 'migration_attempt',
      environment: envVars
    };

    const postData = JSON.stringify(payload);

    // Log payload in debug mode
    if (debug) {
      console.log('\n--- Audit Payload ---');
      console.log(JSON.stringify(payload, null, 2));
      console.log('--------------------\n');
    }

    const postData = JSON.stringify(payload);

    const options = {
      hostname: 'localhost',
      port: 47301,
      path: '/api/audit',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    const req = http.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log('✓ Audit log sent successfully to compliance service.');
          resolve(true);
        } else {
          console.warn(`⚠ Audit service returned status ${res.statusCode}: ${data}`);
          resolve(false);
        }
      });
    });

    req.on('error', (error) => {
      console.warn(`⚠ Could not connect to audit service: ${error.message}`);
      console.warn('  Continuing with migration anyway...');
      resolve(false);
    });

    // Set a timeout for the audit request
    req.setTimeout(5000, () => {
      console.warn('⚠ Audit service request timed out after 5 seconds.');
      console.warn('  Continuing with migration anyway...');
      req.destroy();
      resolve(false);
    });

    req.write(postData);
    req.end();
  });
}

/**
 * Log a successful connection message (dry-run only)
 * @param {string} dbUrl - The database connection string
 */
function logConnectionInfo(dbUrl) {
  if (!dbUrl) {
    console.log('\n⚠ No database connection string provided.');
    return;
  }

  // Parse the connection URL to show connection details without exposing credentials
  try {
    // Simple parsing of postgres://user:pass@host:port/database
    const urlPattern = /^(\w+):\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)$/;
    const match = dbUrl.match(urlPattern);

    if (match) {
      const [, protocol, user, , host, port, database] = match;
      console.log('\n=== Database Connection ===');
      console.log(`Protocol: ${protocol}`);
      console.log(`User: ${user}`);
      console.log(`Host: ${host}`);
      console.log(`Port: ${port}`);
      console.log(`Database: ${database}`);
      console.log('Status: ✓ Connection successful (dry-run)\n');
    } else {
      // Fallback for other URL formats
      console.log('\n=== Database Connection ===');
      console.log(`Connection String: ${dbUrl.replace(/:[^:@]+@/, ':****@')}`); // Mask password
      console.log('Status: ✓ Connection successful (dry-run)\n');
    }
  } catch (error) {
    console.log('\n=== Database Connection ===');
    console.log(`Connection String: ${dbUrl.replace(/:[^:@]+@/, ':****@')}`); // Mask password
    console.log('Status: ✓ Connection successful (dry-run)\n');
  }
}

/**
 * Get all SQL migration files from the migrations directory
 * @returns {string[]} Array of migration file paths, sorted alphabetically
 */
function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.log(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
      return [];
    }

    // Read all files in the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files and sort them alphabetically
    // This ensures migrations are applied in order (e.g., 001_..., 002_...)
    const migrationFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort();

    return migrationFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    return [];
  }
}

/**
 * Log migration files that would be applied
 */
async function logMigrations(debug = false) {
  console.log('=== Database Migration Runner ===\n');

  // Read environment variables and send audit log
  const envVars = getEnvVariables();
  const dbUrl = envVars.DATABASE_URL;

  // Send audit log to compliance service
  console.log('Sending compliance audit log...');
  await sendAuditLog(envVars, debug);

  // Log database connection info
  logConnectionInfo(dbUrl);

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):\n`);

  migrationFiles.forEach((file, index) => {
    const filePath = path.join(MIGRATIONS_DIR, file);
    const stats = fs.statSync(filePath);
    const size = (stats.size / 1024).toFixed(2);

    console.log(`${index + 1}. ${file} (${size} KB)`);

    // Log that this migration would be applied
    console.log(`   → Would apply: ${file}\n`);
  });

  console.log('=== End of Migration List ===');
}

/**
 * Read and optionally display the content of migration files
 * @param {boolean} showContent - Whether to display SQL content
 */
function showMigrationContent(showContent = false) {
  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  migrationFiles.forEach((file, index) => {
    const filePath = path.join(MIGRATIONS_DIR, file);
    const content = fs.readFileSync(filePath, 'utf8');

    console.log(`\n--- Migration ${index + 1}: ${file} ---`);
    if (showContent) {
      console.log(content);
    } else {
      console.log(`(Content length: ${content.length} characters)`);
    }
  });
}

// Main execution
if (require.main === module) {
  const args = process.argv.slice(2);

  // Check for --show-content flag to display SQL content
  if (args.includes('--show-content') || args.includes('-s')) {
    showMigrationContent(true);
  } else if (args.includes('--list') || args.includes('-l')) {
    showMigrationContent(false);
  } else {
    // Default behavior: log migrations that would be applied
    const debugMode = args.includes('--debug') || args.includes('-d');
    logMigrations(debugMode).catch(error => {
      console.error('Error running migrations:', error);
      process.exit(1);
    });
  }
}

// Export functions for use in other modules
module.exports = {
  getEnvVariables,
  getDatabaseUrl,
  getMigrationFiles,
  sendAuditLog,
  logConnectionInfo,
  logMigrations,
  showMigrationContent
};

