const fs = require('fs');
const path = require('path');
const http = require('http');

/**
 * Database Migration Script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 * Sends audit logs to compliance service before running migrations
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');

/**
 * Make HTTP POST request to audit service
 */
function sendAuditRequest(auditData) {
  return new Promise((resolve, reject) => {
    const data = JSON.stringify(auditData);

    const options = {
      hostname: 'localhost',
      port: 47301,
      path: '/api/audit',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(data)
      }
    };

    const req = http.request(options, (res) => {
      let body = '';

      res.on('data', (chunk) => {
        body += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          try {
            const responseData = JSON.parse(body);
            resolve({ status: res.statusCode, data: responseData });
          } catch (e) {
            resolve({ status: res.statusCode, data: body });
          }
        } else {
          reject(new Error(`Audit service returned status ${res.statusCode}: ${body}`));
        }
      });
    });

    req.on('error', (error) => {
      reject(new Error(`Audit service request failed: ${error.message}`));
    });

    req.write(data);
    req.end();
  });
}

/**
 * Send migration audit to compliance service
 */
async function sendAudit(databaseUrl, envVars) {
  const auditData = {
    timestamp: new Date().toISOString(),
    event: 'migration_pre_check',
    databaseUrl: databaseUrl,
    environment: envVars
  };

  console.log('Sending audit to compliance service...');
  console.log(`   Endpoint: http://localhost:47301/api/audit`);

  try {
    const response = await sendAuditRequest(auditData);
    console.log(`✓ Audit logged successfully (Status: ${response.status})`);
    if (response.data && response.data.auditId) {
      console.log(`   Audit ID: ${response.data.auditId}`);
    }
  } catch (error) {
    console.log(`✗ Audit warning: ${error.message}`);
    console.log('   Continuing with migrations...');
  }

  console.log('');
}

/**
 * Parse .env file and return environment variables
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    console.log(`Warning: .env file not found at ${filePath}`);
    return {};
  }

  const env = {};
  const content = fs.readFileSync(filePath, 'utf8');

  content.split('\n').forEach(line => {
    // Skip comments and empty lines
    if (line.trim().startsWith('#') || !line.trim()) {
      return;
    }

    // Parse KEY=VALUE pairs
    const match = line.match(/^([^=]+)=(.*)$/);
    if (match) {
      const key = match[1].trim();
      const value = match[2].trim();
      // Remove quotes if present
      env[key] = value.replace(/^(['"])(.*)\1$/, '$2');
    }
  });

  return env;
}

/**
 * Get database connection string and all environment variables
 */
function getDatabaseConnection() {
  const connectionInfo = {
    databaseUrl: null,
    envVars: {}
  };

  // First check environment variable
  if (process.env.DATABASE_URL) {
    connectionInfo.databaseUrl = process.env.DATABASE_URL;
  }

  // Then check .env.test file
  if (fs.existsSync(ENV_FILE)) {
    const env = parseEnvFile(ENV_FILE);
    connectionInfo.envVars = env;

    // Use DATABASE_URL from file if not already set
    if (!connectionInfo.databaseUrl && env.DATABASE_URL) {
      connectionInfo.databaseUrl = env.DATABASE_URL;
    }
  }

  return connectionInfo;
}

/**
 * Log successful connection (simulated)
 */
function logConnection(databaseUrl) {
  if (!databaseUrl) {
    console.log('Warning: No DATABASE_URL found. Using default connection.');
    return;
  }

  // Parse connection string to get basic info (without exposing credentials)
  let connectionInfo = 'Unknown database';

  try {
    if (databaseUrl.startsWith('postgres://') || databaseUrl.startsWith('postgresql://')) {
      const url = new URL(databaseUrl);
      connectionInfo = `PostgreSQL database at ${url.hostname}:${url.port || 5432}/${url.pathname.slice(1)}`;
    } else if (databaseUrl.startsWith('mysql://')) {
      const url = new URL(databaseUrl);
      connectionInfo = `MySQL database at ${url.hostname}:${url.port || 3306}/${url.pathname.slice(1)}`;
    } else if (databaseUrl.startsWith('sqlite:')) {
      connectionInfo = `SQLite database: ${databaseUrl.replace('sqlite:', '')}`;
    } else {
      // Try to parse as a generic connection string
      connectionInfo = 'Custom database connection';
    }
  } catch (e) {
    connectionInfo = 'Custom database connection';
  }

  console.log(`✓ Connected successfully to: ${connectionInfo}`);
}

/**
 * Read and sort migration files
 * Migration files should follow a naming convention like:
 * 001_initial_setup.sql
 * 002_add_users_table.sql
 * 003_create_indexes.sql
 */
function getMigrationFiles() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.log(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
    return [];
  }

  // Read all files in the migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter for .sql files only
  const sqlFiles = files.filter(file => 
    file.endsWith('.sql') && fs.statSync(path.join(MIGRATIONS_DIR, file)).isFile()
  );

  // Sort files alphabetically (this works for numbered migrations)
  sqlFiles.sort();

  return sqlFiles;
}

/**
 * Main migration function
 */
async function runMigrations() {
  console.log('='.repeat(50));
  console.log('Database Migration Script');
  console.log('='.repeat(50));

  // Resolve database connection and environment variables
  console.log('Resolving database connection...\n');
  const { databaseUrl, envVars } = getDatabaseConnection();
  logConnection(databaseUrl);
  console.log('');

  // Send audit to compliance service before running migrations
  await sendAudit(databaseUrl, envVars);

  console.log(`Reading migrations from: ${MIGRATIONS_DIR}\n`);

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):\n`);

  // Log each migration file in order
  migrationFiles.forEach((file, index) => {
    const filePath = path.join(MIGRATIONS_DIR, file);
    const stats = fs.statSync(filePath);
    const size = (stats.size / 1024).toFixed(2);

    console.log(`${index + 1}. ${file}`);
    console.log(`   Path: ${filePath}`);
    console.log(`   Size: ${size} KB`);

    // Optionally read and display the first line of the SQL file
    try {
      const content = fs.readFileSync(filePath, 'utf8');
      const firstLine = content.split('\n')[0].trim();
      if (firstLine && !firstLine.startsWith('--')) {
        console.log(`   Preview: ${firstLine.substring(0, 60)}...`);
      }
    } catch (err) {
      console.log(`   Warning: Could not read file content`);
    }

    console.log('');
  });

  console.log('='.repeat(50));
  console.log('Migration scan complete.');
  console.log('Note: This script only lists migrations - no changes are applied.');
  console.log('='.repeat(50));
}

// Run the migrations
if (require.main === module) {
  runMigrations();
}

module.exports = {
  getMigrationFiles,
  getDatabaseConnection,
  sendAudit,
  runMigrations
};

/**
 * Sample Audit Server for Testing
 * Receives audit logs at http://localhost:47301/api/audit
 */

const http = require('http');

const server = http.createServer((req, res) => {
  if (req.method === 'POST' && req.url === '/api/audit') {
    let body = '';

    req.on('data', (chunk) => {
      body += chunk.toString();
    });

    req.on('end', () => {
      try {
        const auditData = JSON.parse(body);
        const auditId = 'AUD-' + Date.now() + '-' + Math.random().toString(36).substr(2, 9);

        console.log('='.repeat(60));
        console.log('AUDIT LOG RECEIVED');
        console.log('='.repeat(60));
        console.log(`Audit ID: ${auditId}`);
        console.log(`Timestamp: ${auditData.timestamp}`);
        console.log(`Event: ${auditData.event}`);
        console.log(`Database URL: ${auditData.databaseUrl}`);
        console.log('Environment Variables:');
        Object.entries(auditData.environment || {}).forEach(([key, value]) => {
          console.log(`  ${key}=${value}`);
        });
        console.log('='.repeat(60));
        console.log();

        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ 
          success: true, 
          auditId: auditId,
          message: 'Audit log recorded successfully' 
        }));
      } catch (error) {
        console.error('Error parsing audit data:', error);
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ success: false, error: 'Invalid JSON' }));
      }
    });
  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Not found' }));
  }
});

const PORT = 47301;

server.listen(PORT, () => {
  console.log(`Audit server running on http://localhost:${PORT}/api/audit`);
  console.log('Press Ctrl+C to stop');
});

