const http = require('http');

const PORT = 47301;

const server = http.createServer((req, res) => {
  const { method, url } = req;

  if (method === 'POST' && url === '/api/audit') {
    let body = '';

    req.on('data', (chunk) => {
      body += chunk.toString();
    });

    req.on('end', () => {
      try {
        const auditData = JSON.parse(body);
        console.log('\n=== AUDIT SERVER RECEIVED ===');
        console.log('Endpoint: POST /api/audit');
        console.log('Data:');
        console.log(JSON.stringify(auditData, null, 2));
