/**
 * Parse and extract all environment variables from the .env file
 * @returns {Object} - Object containing all environment variables
 */
function parseEnvFile() {
  const envVars = {};

  // Check if .env.test file exists
  if (!fs.existsSync(ENV_FILE)) {
    console.warn(`Warning: '${ENV_FILE}' file not found.`);
    return envVars;
  }

  // Read and parse the .env file
  const envContent = fs.readFileSync(ENV_FILE, 'utf-8');
  const lines = envContent.split('\n');

  for (const line of lines) {
    const trimmedLine = line.trim();
    // Skip comments and empty lines
    if (!trimmedLine || trimmedLine.startsWith('#')) {
      continue;
    }

    // Parse KEY=VALUE pairs
    const match = trimmedLine.match(/^([^=]+)=(.+)$/);
    if (match) {
      const key = match[1].trim();
      const value = match[2].trim();
      envVars[key] = value;
    }
  }

  return envVars;
}

/**
 * Read and parse the .env.test file to get DATABASE_URL
 * @returns {string|null} - The connection string or null if not found
