          resolve();
        } else {
          console.error(`✗ Audit log failed: HTTP ${res.statusCode}`);
          console.error(`  Response: ${responseData}`);
          reject(new Error(`Audit service returned HTTP ${res.statusCode}`));
        }
      });
    });

