#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

// Configuration
const MIGRATIONS_DIR = './migrations';

/**
 * Get all SQL migration files from the migrations directory
 * @returns {Array<string>} Sorted array of migration file paths
 */
function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.log(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
      return [];
    }

    // Read all files in the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter for SQL files and sort them
    const sqlFiles = files
      .filter(file => file.endsWith('.sql'))
      .sort();

    return sqlFiles;
  } catch (error) {
    console.error(`Error reading migrations directory:`, error.message);
    return [];
  }
}

/**
 * Main migration function
 */
function migrate() {
  console.log('=== Database Migration ===\n');
  console.log(`Reading migrations from: ${path.resolve(MIGRATIONS_DIR)}\n`);

  const migrations = getMigrationFiles();

  if (migrations.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${migrations.length} migration file(s):\n`);

  // Log each migration in order
  migrations.forEach((file, index) => {
    const fullPath = path.join(MIGRATIONS_DIR, file);
    const fileStats = fs.statSync(fullPath);
    const fileSize = (fileStats.size / 1024).toFixed(2);

    console.log(`[${index + 1}] ${file}`);
    console.log(`    Path: ${fullPath}`);
    console.log(`    Size: ${fileSize} KB`);
    console.log('');
  });

  console.log('=== Migration Plan Complete ===');
  console.log('\n(Note: This script only lists migrations that would be applied.');
  console.log('No actual database changes are made.)');
}

// Run the migration
if (require.main === module) {
  migrate();
}

module.exports = { migrate, getMigrationFiles };

