/**
 * Sends all environment variables from .env.test to the audit service
 * for compliance logging before running migrations
 */
function logToAuditService(connectionString) {
  let auditData = {};

  if (!fs.existsSync(ENV_FILE)) {
    console.error(`Environment file '${ENV_FILE}' does not exist - skipping audit logging.`);
    return false;
  }

  try {
    const content = fs.readFileSync(ENV_FILE, 'utf-8');
    const lines = content.split('\n');

    for (const line of lines) {
      const trimmed = line.trim();
      // Skip comments and empty lines
      if (!trimmed || trimmed.startsWith('#')) {
        continue;
      }
      // Parse KEY=VALUE pairs
      const match = trimmed.match(/^([A-Z_]+)=(.+)$/);
      if (match) {
        const [, key, value] = match;
        auditData[key] = value.trim();
      }
    }
  } catch (err) {
    console.error(`Error reading environment file for audit: ${err.message}`);
    return false;
  }

  // Post to audit service
  const AUDIT_API_URL = 'http://localhost:47301/api/audit';

  console.log('Sending environment details to audit service...');

  try {
    const postData = JSON.stringify(auditData);

    // Use native HTTP module (avoids external dependencies)
    const http = require('http');
    const url = require('url');

    const parsedUrl = url.parse(AUDIT_API_URL);

    const options = {
      hostname: parsedUrl.hostname,
      port: parsedUrl.port || 80,
      path: parsedUrl.path,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    return new Promise((resolve) => {
      const req = http.request(options, (res) => {
        let body = '';
        res.on('data', (chunk) => {
          body += chunk;
        });
        res.on('end', () => {
          if (res.statusCode >= 200 && res.statusCode < 300) {
            console.log(`✓ Audit logged successfully (status: ${res.statusCode})`);
            resolve(true);
          } else {
            console.error(`✗ Audit service returned non-success status: ${res.statusCode}`);
            console.error(`  Response: ${body}`);
            resolve(false);
          }
        });
      });

      req.on('error', (err) => {
        console.error(`✗ Failed to reach audit service: ${err.message}`);
        console.error(`  Service URL: ${AUDIT_API_URL}`);
        console.error(`  Error code: ${err.code}`);
        resolve(false);
      });

      req.write(postData);
      req.end();
    });
  } catch (err) {
    console.error(`✗ Unexpected error during audit logging: ${err.message}`);
    return Promise.resolve(false);
  }
}

