/**
 * Database Migration Script
 * 
 * Reads SQL migration files from ./migrations/ directory
 * and logs each filename in the order they would be applied.
 * Also resolves DATABASE_URL from .env.test file.
 */

const MIGRATIONS_DIR = './migrations';
const ENV_FILE = '.env.test';

/**
 * Parse .env file and return key-value pairs
 * @param {string} filePath - Path to the .env file
 * @returns {Object} Parsed environment variables
 */
function parseEnvFile(filePath) {
  if (!fs.existsSync(filePath)) {
    return {};
  }

  const content = fs.readFileSync(filePath, 'utf8');
  const envVars = {};

  content.split('\n').forEach(line => {
    const trimmed = line.trim();
    // Skip empty lines and comments
    if (!trimmed || trimmed.startsWith('#')) {
      return;
    }

    // Parse KEY=VALUE (handle values with quotes)
    const match = trimmed.match(/^([^=]+)=(.*)$/);
    if (match) {
      const key = match[1].trim();
      let value = match[2].trim();

      // Remove surrounding quotes if present
      if ((value.startsWith('"') && value.endsWith('"')) ||
          (value.startsWith("'") && value.endsWith("'"))) {
        value = value.slice(1, -1);
      }

      envVars[key] = value;
    }
  });

  return envVars;
}

/**
 * Resolve the database connection string
 * @returns {string|null} The database URL or null if not found
 */
function getDatabaseUrl() {
  // First, check if DATABASE_URL is already in environment
  if (process.env.DATABASE_URL) {
    return process.env.DATABASE_URL;
  }

  // Try to read from .env.test file
  const envVars = parseEnvFile(ENV_FILE);

  if (envVars.DATABASE_URL) {
    return envVars.DATABASE_URL;
  }

  return null;
}

