#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = './migrations';

/**
 * Get all SQL migration files from the migrations directory
 * @returns {Array<string>} Array of migration file paths
 */
function getMigrationFiles() {
  const migrationsDir = path.resolve(MIGRATIONS_DIR);

  // Check if migrations directory exists
  if (!fs.existsSync(migrationsDir)) {
    console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
    process.exit(1);
  }

  // Read all files in the directory
  const files = fs.readdirSync(migrationsDir);

  // Filter for SQL files only (case insensitive)
  const sqlFiles = files.filter(file => 
    file.toLowerCase().endsWith('.sql')
  );

  // Sort files alphabetically to ensure consistent order
  sqlFiles.sort();

  return sqlFiles;
}

/**
 * Read and apply a migration file
 * @param {string} filename - The migration filename
 */
function applyMigration(filename) {
  const migrationPath = path.join(MIGRATIONS_DIR, filename);

  logMigration(filename);

  // Read the SQL content (could be used to execute the migration)
  const sqlContent = fs.readFileSync(migrationPath, 'utf-8');

  // Here you would typically execute the SQL against your database
  // For now, we're just logging which files would be applied

  return sqlContent;
}

/**
 * Log a migration being applied
 * @param {string} filename - The migration filename
 */
function logMigration(filename) {
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] Would apply migration: ${filename}`);
}

/**
 * Main migration runner
 */
function runMigrations() {
  console.log('Starting migration check...');
  console.log(`Reading migrations from: ${MIGRATIONS_DIR}\n`);

  const migrationFiles = getMigrationFiles();

  if (migrationFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${migrationFiles.length} migration file(s):\n`);

  // Apply migrations in order
  const appliedMigrations = [];
  for (const filename of migrationFiles) {
    applyMigration(filename);
    appliedMigrations.push(filename);
  }

  console.log(`\nMigration check complete. ${appliedMigrations.length} file(s) would be applied.`);
}

// Run the migrations if this script is executed directly
if (require.main === module) {
  runMigrations();
}

// Export functions for testing or programmatic use
module.exports = {
  getMigrationFiles,
  applyMigration,
  logMigration,
  runMigrations
};

