  });
}

/**
 * Log a successful database connection (simulated)
 * @param {string} databaseUrl - The database connection string
 */
function logConnectionSuccess(databaseUrl) {
  // Mask sensitive parts of the URL for security
  const maskedUrl = databaseUrl.replace(/:[^:@]+@/, ':****@');
  const timestamp = new Date().toISOString();
  console.log(`[${timestamp}] Connected to database: ${maskedUrl}`);
