const fs = require('fs');
const path = require('path');

/**
 * Database migration script
 * Reads SQL files from ./migrations/ directory and logs each filename in order
 */

const MIGRATIONS_DIR = './migrations';

/**
 * Get all SQL migration files from the migrations directory
 * @returns {string[]} Array of migration file paths, sorted by filename
 */
function getMigrationFiles() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.log(`Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
    return [];
  }

  // Read all files in the migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter for SQL files
  const sqlFiles = files
    .filter(file => file.endsWith('.sql'))
    .sort(); // Sort alphabetically to ensure consistent order

  return sqlFiles;
}

/**
 * Main migration function
 * Logs each migration filename that would be applied
 */
function migrate() {
  console.log('=== Database Migration ===\n');

  const migrations = getMigrationFiles();

  if (migrations.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log(`Found ${migrations.length} migration file(s):\n`);

  migrations.forEach((file, index) => {
    const fullPath = path.join(MIGRATIONS_DIR, file);

    // Get file stats for additional info
    const stats = fs.statSync(fullPath);
    const fileSize = (stats.size / 1024).toFixed(2);

    console.log(`${index + 1}. ${file} (${fileSize} KB)`);
    console.log(`   Full path: ${fullPath}`);
  });

  console.log('\n=== Summary ===');
  console.log(`Would apply ${migrations.length} migration(s).`);
  console.log('Note: This is a dry run. No SQL was executed.');
}

// Run migrations if this script is executed directly
if (require.main === module) {
  migrate();
}

// Export functions for testing or programmatic use
module.exports = {
  getMigrationFiles,
  migrate
};

