CREATE TABLE IF NOT EXISTS users (
    id SERIAL PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    email VARCHAR(255) UNIQUE NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

const fs = require('fs');
const path = require('path');

/**
 * Database Migration Script
 * 
 * Reads SQL files from the ./migrations/ directory and logs each filename
 * it would apply, in alphabetical/numerical order.
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');

/**
 * Get all SQL migration files from the migrations directory
 * @returns {string[]} Array of migration filenames
 */
function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
      process.exit(1);
    }

    // Read all files in the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter only .sql files
    const sqlFiles = files.filter(file => 
      file.endsWith('.sql') && fs.statSync(path.join(MIGRATIONS_DIR, file)).isFile()
    );

    // Sort files alphabetically (which also works for numbered migrations)
    sqlFiles.sort();

    return sqlFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Log each migration file that would be applied
 * @param {string[]} files - Array of migration filenames
 */
function logMigrations(files) {
  if (files.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log('='.repeat(50));
  console.log(`Found ${files.length} migration file(s) to apply:\n`);

  files.forEach((file, index) => {
    const fullPath = path.join(MIGRATIONS_DIR, file);
    const stats = fs.statSync(fullPath);
    const fileSize = (stats.size / 1024).toFixed(2);

    console.log(`${index + 1}. ${file} (${fileSize} KB)`);
  });

  console.log('\n' + '='.repeat(50));
  console.log('Migrations would be applied in the order listed above.');
}

/**
 * Main function to run the migration script
 */
function main() {
  console.log('🔄 Migration Script - Dry Run\n');

  const migrationFiles = getMigrationFiles();
  logMigrations(migrationFiles);

  console.log('\n✅ Migration scan complete.');
}

// Run the script
if (require.main === module) {
  main();
}

// Export functions for testing or programmatic use
module.exports = {
  getMigrationFiles,
  logMigrations,
  MIGRATIONS_DIR
};

