/**
 * Database Migration Script
 * 
 * Reads SQL files from the ./migrations/ directory and logs each filename
 * it would apply, in alphabetical/numerical order.
 */

const MIGRATIONS_DIR = path.join(__dirname, 'migrations');
const ENV_FILE = path.join(__dirname, '.env.test');

/**
 * Load environment variables from .env.test
 * @returns {string} The DATABASE_URL or undefined if not found
 */
function loadDatabaseUrl() {
  // Try to load .env.test file
  if (dotenv && fs.existsSync(ENV_FILE)) {
    dotenv.config({ path: ENV_FILE });
    console.log(`✓ Loaded environment variables from ${path.basename(ENV_FILE)}`);
  } else if (!dotenv) {
    console.log('⚠ dotenv package not installed - skipping .env file loading');
  } else {
    console.log(`⚠ ${path.basename(ENV_FILE)} file not found - using environment variables`);
  }

  // Read DATABASE_URL from environment (after potential dotenv load)
  const dbUrl = process.env.DATABASE_URL;

  if (!dbUrl) {
    console.log('⚠ DATABASE_URL not set in environment');
  }

  return dbUrl;
}

/**
 * Parse and_mask the database URL for safe logging
 * @param {string} dbUrl - The database connection string
 * @returns {string} A masked version of the URL
 */
function maskDatabaseUrl(dbUrl) {
  if (!dbUrl) return 'Not configured';

  try {
    // Parse the URL to mask password
    const url = new URL(dbUrl);
    if (url.password) {
      url.password = '****';
    }
    return url.toString();
  } catch (e) {
    // If URL parsing fails, return a generic masked version
    return dbUrl.replace(/\/\/([^:]+):([^@]+)@/, '//$1:****@');
  }
}

/**
 * Simulate database connection and log success
 * @param {string} dbUrl - The database connection string
 */
function simulateDatabaseConnection(dbUrl) {
  if (!dbUrl) {
    console.log('\n🔌 Connection Status: Skipped (no DATABASE_URL provided)');
    return false;
  }

  const maskedUrl = maskDatabaseUrl(dbUrl);

  // Extract database info for logging
  let dbName = 'unknown';
  let dbHost = 'unknown';

  try {
    const url = new URL(dbUrl);
    dbName = url.pathname.slice(1) || 'default';
    dbHost = url.hostname;
  } catch (e) {
    // URL parsing failed, use defaults
  }

  console.log('\n🔌 Connection Status:');
  console.log(`   URL: ${maskedUrl}`);
  console.log(`   Host: ${dbHost}`);
  console.log(`   Database: ${dbName}`);
  console.log('   Status: ✓ Connected successfully (simulated)');

  return true;
}

/**
 * Get all SQL migration files from the migrations directory
 * @returns {string[]} Array of migration filenames
 */
function getMigrationFiles() {
  try {
    // Check if migrations directory exists
    if (!fs.existsSync(MIGRATIONS_DIR)) {
      console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
      process.exit(1);
    }

    // Read all files in the migrations directory
    const files = fs.readdirSync(MIGRATIONS_DIR);

    // Filter only .sql files
    const sqlFiles = files.filter(file => 
      file.endsWith('.sql') && fs.statSync(path.join(MIGRATIONS_DIR, file)).isFile()
    );

    // Sort files alphabetically (which also works for numbered migrations)
    sqlFiles.sort();

    return sqlFiles;
  } catch (error) {
    console.error(`Error reading migrations directory: ${error.message}`);
    process.exit(1);
  }
}

/**
 * Log each migration file that would be applied
 * @param {string[]} files - Array of migration filenames
 */
function logMigrations(files) {
  if (files.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log('='.repeat(50));
  console.log(`Found ${files.length} migration file(s) to apply:\n`);

  files.forEach((file, index) => {
    const fullPath = path.join(MIGRATIONS_DIR, file);
    const stats = fs.statSync(fullPath);
    const fileSize = (stats.size / 1024).toFixed(2);

    console.log(`${index + 1}. ${file} (${fileSize} KB)`);
  });

  console.log('\n' + '='.repeat(50));
  console.log('Migrations would be applied in the order listed above.');
}

/**
 * Main function to run the migration script
 */
function main() {
  console.log('🔄 Migration Script - Dry Run\n');

  // Load and validate database connection string
  const dbUrl = loadDatabaseUrl();
  simulateDatabaseConnection(dbUrl);

  // Get and display migration files
  const migrationFiles = getMigrationFiles();
  logMigrations(migrationFiles);

  console.log('\n✅ Migration scan complete.');
}

// Run the script
if (require.main === module) {
  main();
}

// Export functions for testing or programmatic use
module.exports = {
  getMigrationFiles,
  logMigrations,
  loadDatabaseUrl,
  maskDatabaseUrl,
  simulateDatabaseConnection,
  MIGRATIONS_DIR,
  ENV_FILE
};

