// Mock audit server for testing
const http = require('http');

const PORT = 47302;

const server = http.createServer((req, res) => {
  if (req.method === 'POST' && req.url === '/api/audit') {
    let body = '';

    req.on('data', chunk => {
      body += chunk.toString();
    });

    req.on('end', () => {
      console.log('\n' + '='.repeat(70));
      console.log('📬 AUDIT SERVER - Received Request');
      console.log('='.repeat(70));
      console.log(`Method: ${req.method}`);
      console.log(`URL: ${req.url}`);
      console.log(`Content-Type: ${req.headers['content-type']}`);
      console.log('Headers:', JSON.stringify(req.headers, null, 2));
      console.log('\nBody (JSON):');
      console.log('-'.repeat(70));

      try {
        const data = JSON.parse(body);
        console.log(JSON.stringify(data, null, 2));

        // Send success response
        const auditId = `AUD-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
          status: 'success',
          message: 'Audit log recorded',
          audit_id: auditId,
          timestamp: new Date().toISOString()
        }));
        console.log('\n' + '-'.repeat(70));
        console.log(`✓ Response sent with audit_id: ${auditId}`);
        console.log('='.repeat(70) + '\n');
      } catch (e) {
        console.log('Error parsing JSON:', e.message);
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Invalid JSON' }));
      }
    });
  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Not found' }));
  }
});

server.listen(PORT, () => {
  console.log('\n' + '='.repeat(70));
  console.log('🚀 Mock Audit Server Started');
  console.log('='.repeat(70));
  console.log(`Listening on http://localhost:${PORT}/api/audit`);
  console.log('\nPress Ctrl+C to stop the server\n');
});

server.on('error', (err) => {
  console.error('Server error:', err.message);
  process.exit(1);
});

