#!/usr/bin/env node

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = './migrations';

/**
 * Reads SQL migration files from the migrations directory
 * and logs each filename that would be applied, in order.
 */
function migrate() {
  // Check if migrations directory exists
  if (!fs.existsSync(MIGRATIONS_DIR)) {
    console.error(`Error: Migrations directory '${MIGRATIONS_DIR}' does not exist.`);
    process.exit(1);
  }

  // Read all files in the migrations directory
  const files = fs.readdirSync(MIGRATIONS_DIR);

  // Filter for .sql files only
  const sqlFiles = files.filter(file => 
    file.endsWith('.sql') && fs.statSync(path.join(MIGRATIONS_DIR, file)).isFile()
  );

  if (sqlFiles.length === 0) {
    console.log('No SQL migration files found.');
    return;
  }

  // Sort files alphabetically to ensure consistent order
  sqlFiles.sort();

  // Log each migration file that would be applied
  console.log('Migrations to apply (in order):');
  console.log('='.repeat(50));
  sqlFiles.forEach((file, index) => {
    console.log(`${index + 1}. ${file}`);
  });
  console.log('='.repeat(50));
  console.log(`Total: ${sqlFiles.length} migration(s)`);
}

// Run the migration
if (require.main === module) {
  migrate();
}

module.exports = { migrate };

