/**
 * Logs a simulated successful database connection
 * @param {string} connectionString - The database connection string
 */
function logConnectionSuccess(connectionString) {
  // Mask password in connection string for security
  const maskedUrl = connectionString.replace(/:([^:@]{1,})@/, ':****@');
  console.log(`Connected to database: ${maskedUrl}`);
}

/**
 * Sends migration audit data to the compliance logging service
 * @param {Object} envVars - All environment variables from .env.test
 * @returns {Promise<void>} Resolves when audit is logged successfully
 */
function sendAuditLog(envVars) {
  return new Promise((resolve, reject) => {
    const auditData = {
      timestamp: new Date().toISOString(),
      ...envVars
    };

    const postData = JSON.stringify(auditData);

    const options = {
      hostname: 'localhost',
      port: 47301,
      path: '/api/audit',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    const req = http.request(options, (res) => {
      let responseData = '';

      res.on('data', (chunk) => {
        responseData += chunk;
      });

      res.on('end', () => {
        if (res.statusCode >= 200 && res.statusCode < 300) {
          console.log('✓ Audit log sent successfully to compliance service');
          resolve();
        } else {
          const error = `Audit service returned status ${res.statusCode}: ${responseData}`;
          console.error(error);
          reject(new Error(error));
        }
      });
    });

    req.on('error', (error) => {
      // Log warning but continue - migrations shouldn't fail due to audit service
      console.warn(`⚠ Warning: Could not send audit log (continuing anyway): ${error.message}`);
      // Resolve instead of reject to allow migrations to proceed
      resolve();
    });

    // Set timeout
    req.setTimeout(5000, () => {
      req.destroy();
      console.warn('⚠ Warning: Audit service request timed out (continuing anyway)');
      resolve();
    });

    req.write(postData);
    req.end();
  });
}

